function J = addExponentialNoise(I, a)
%ADDEXPONENTIALNOISE Additive exponential noise (Gonzalez & Woods, noise models).
%   J = addExponentialNoise(I, a) adds z with the exponential PDF
%
%       p(z) = a exp(-a z)   for z >= 0
%       mean = 1/a,   variance = 1/a^2
%
%   The special case b = 1 of the Erlang PDF; also found in laser imaging.
%   Generated by inverting the CDF:  z = -ln(1 - U) / a.

if nargin < 2 || isempty(a), a = 10; end
if a <= 0, error('ImageLab:invalidParameter', 'a must be > 0.'); end
I = toDouble(I);
z = -log(1 - rand(size(I))) / a;
J = min(max(I + z, 0), 1);
end
